/*
 * ESP32 + RFID-RC522: телефон -> EEPROM -> "Блокнот" на ПК
 *
 * Читает UID и (если телефон в режиме эмуляции NFC-карты) NDEF-данные,
 * сохраняет записи в EEPROM и выгружает базу в Блокнот как USB-клавиатура
 * (ESP32-S2/S3) или в Serial-монитор (классический ESP32).
 *
 * Библиотека: MFRC522 by GithubCommunity (Library Manager).
 *
 * Распиновка: MOSI=GPIO13, MISO=GPIO12, SCK=GPIO18, SS=GPIO5, RST=GPIO4.
 * IRQ на GPIO11 подключён, но не задействован (библиотека опрашивает
 * модуль по SPI, прерывание не требуется).
 */
#include <SPI.h>
#include <EEPROM.h>
#include <MFRC522.h>          // объявляет и MFRC522Extended

#define RST_PIN   4
#define SS_PIN    5
#define SCK_PIN   18
#define MOSI_PIN  13
#define MISO_PIN  12
#define IRQ_PIN   11     // не используется библиотекой, оставлен под прерывание

#define EEPROM_SIZE 6000
#define MAX_RECORDS 40
#define UID_MAX     10
#define DATA_MAX    120

struct Record {
  uint32_t ts;                // millis() в момент записи
  uint8_t  uidLen;
  uint8_t  uid[UID_MAX];
  uint8_t  dataLen;
  char     data[DATA_MAX + 1];
};

MFRC522Extended rfid(SS_PIN, RST_PIN);

#if defined(SOC_USB_OTG_SUPPORTED)   // только ESP32-S2 / S3 / C3
  #include <USBHIDKeyboard.h>
  USBHIDKeyboard Keyboard;
  #define USB_KB 1
#else
  #define USB_KB 0
#endif

uint8_t recCount = 0;
byte isoPcb = 0x02;           // чередование блоков ISO-DEP: 0x02 / 0x03

// ---------- EEPROM ----------

Record loadRecord(uint8_t i) {
  Record r;
  EEPROM.get(1 + i * sizeof(Record), r);
  return r;
}

void saveRecordAt(uint8_t i, const Record &r) {
  EEPROM.put(1 + i * sizeof(Record), r);
}

void addRecord(uint32_t ts, const uint8_t *uid, uint8_t uidLen, const char *data) {
  // дедупликация: по тексту NDEF, если он есть, иначе по UID
  for (uint8_t i = 0; i < recCount; i++) {
    Record r = loadRecord(i);
    bool dup;
    if (data && r.dataLen)
      dup = (strlen(data) == r.dataLen && memcmp(data, r.data, r.dataLen) == 0);
    else
      dup = (r.uidLen == uidLen && memcmp(uid, r.uid, uidLen) == 0);
    if (dup) { r.ts = ts; saveRecordAt(i, r); EEPROM.commit(); return; }
  }
  Record r;
  memset(&r, 0, sizeof(r));
  r.ts = ts;
  r.uidLen = min((uint8_t)uidLen, (uint8_t)UID_MAX);
  memcpy(r.uid, uid, r.uidLen);
  if (data) {
    r.dataLen = min((uint8_t)strlen(data), (uint8_t)DATA_MAX);
    memcpy(r.data, data, r.dataLen);
  }
  // если база полна — затираем самую старую запись (индекс 0)
  uint8_t slot = (recCount < MAX_RECORDS) ? recCount++ : 0;
  saveRecordAt(slot, r);
  EEPROM.write(0, recCount);
  EEPROM.commit();
}

// ---------- обмен APDU с телефоном (Type 4 Tag) ----------

bool apdu(const byte *cmd, byte cmdLen, byte *out, byte *outLen) {
  byte frame[64], resp[64];
  if (cmdLen + 3 > sizeof(frame)) return false;
  frame[0] = isoPcb;
  memcpy(frame + 1, cmd, cmdLen);
  rfid.PCD_CalculateCRC(frame, cmdLen + 1, frame + 1 + cmdLen);

  byte respLen = sizeof(resp);
  if (rfid.PCD_TransceiveData(frame, cmdLen + 3, resp, &respLen, NULL, 0, false)
      != MFRC522::STATUS_OK || respLen < 5) return false;

  isoPcb = (isoPcb == 0x02) ? 0x03 : 0x02;

  // проверка CRC ответа
  byte crc[2];
  rfid.PCD_CalculateCRC(resp, respLen - 2, crc);
  if (crc[0] != resp[respLen - 2] || crc[1] != resp[respLen - 1]) return false;

  // resp = PCB + INF + CRC; в INF последние 2 байта — SW
  byte infLen = respLen - 3;
  if (infLen < 2) return false;
  if (resp[1 + infLen - 2] != 0x90 || resp[1 + infLen - 1] != 0x00) return false;

  infLen -= 2;                                   // убираем SW
  if (*outLen > infLen) *outLen = infLen;
  memcpy(out, resp + 1, *outLen);
  return true;
}

const byte SEL_AID[] = {0x00,0xA4,0x04,0x00,0x07,0xD2,0x76,0x00,0x00,0x85,0x01,0x01,0x00};
const byte SEL_CC[]  = {0x00,0xA4,0x00,0x0C,0x02,0xE1,0x03};
const byte RD_CC[]   = {0x00,0xB0,0x00,0x00,0x0F};

bool readNdefFromPhone(char *out, uint8_t maxOut) {
  byte buf[40]; byte n = sizeof(buf);

  if (!apdu(SEL_AID, sizeof(SEL_AID), buf, &n)) return false;      // NDEF-приложение
  n = sizeof(buf);
  if (!apdu(SEL_CC, sizeof(SEL_CC), buf, &n)) return false;        // Capability Container
  n = sizeof(buf);
  if (!apdu(RD_CC, sizeof(RD_CC), buf, &n) || n < 13) return false;
  uint16_t fileId = ((uint16_t)buf[9] << 8) | buf[10];             // обычно 0xE104

  byte selFile[] = {0x00,0xA4,0x00,0x0C,0x02,(byte)(fileId >> 8),(byte)(fileId & 0xFF)};
  n = sizeof(buf);
  if (!apdu(selFile, sizeof(selFile), buf, &n)) return false;      // NDEF-файл

  const byte RD_LEN[] = {0x00,0xB0,0x00,0x00,0x02};                // NLEN
  n = sizeof(buf);
  if (!apdu(RD_LEN, sizeof(RD_LEN), buf, &n) || n < 2) return false;
  uint16_t nlen = ((uint16_t)buf[0] << 8) | buf[1];
  if (nlen == 0 || nlen > 200) return false;

  byte ndef[200];
  uint16_t off = 0;
  while (off < nlen) {
    byte rd[] = {0x00,0xB0,(byte)(off >> 8),(byte)(off & 0xFF),0x10}; // читать по 16 байт
    n = sizeof(buf);
    if (!apdu(rd, sizeof(rd), buf, &n) || n == 0) return false;
    uint16_t chunk = min((uint16_t)n, (uint16_t)(nlen - off));
    memcpy(ndef + off, buf, chunk);
    off += chunk;
  }
  return parseNdef(ndef, nlen, out, maxOut);
}

// ---------- разбор NDEF ----------

void appendStr(char *dst, uint8_t cap, const char *src, uint16_t len) {
  uint8_t d = strlen(dst);
  for (uint16_t i = 0; i < len && d < cap - 1; i++) dst[d++] = src[i];
  dst[d] = 0;
}

bool parseNdef(const byte *msg, uint16_t len, char *out, uint8_t maxOut) {
  if (len < 5) return false;
  byte hdr = msg[0];
  if ((hdr & 0xC0) != 0xC0) return false;   // только одиночная запись (MB=1, ME=1)
  if (!(hdr & 0x10))        return false;   // только SR (короткий) формат
  uint8_t typeLen = msg[1];
  uint8_t payLen  = msg[2];
  if (4 + typeLen + payLen > len) return false;

  const byte *type    = msg + 4;
  const byte *payload = type + typeLen;
  out[0] = 0;

  if (typeLen == 1 && type[0] == 'T') {                     // текстовая запись
    uint8_t langLen = payload[0] & 0x3F;
    if (1 + langLen >= payLen) return false;
    appendStr(out, maxOut, (const char *)(payload + 1 + langLen), payLen - 1 - langLen);
    return out[0] != 0;
  }
  if (typeLen == 1 && type[0] == 'U') {                     // URI-запись
    static const char *P[] = {"", "http://www.", "https://www.", "http://", "https://",
                              "tel:", "mailto:", "ftp://anonymous:anonymous@ftp.",
                              "ftp://ftp.", "ftps://", "sftp://", "smb://", "urn:nfc:"};
    uint8_t code = payload[0];
    if (code >= sizeof(P) / sizeof(P[0])) return false;
    appendStr(out, maxOut, P[code], strlen(P[code]));
    appendStr(out, maxOut, (const char *)(payload + 1), payLen - 1);
    return true;
  }
  return false;                                             // неизвестный тип записи
}

// ---------- выгрузка ----------

String recordToText(uint8_t i) {
  Record r = loadRecord(i);
  String s = "#" + String(i + 1) + " | UID: ";
  char hex[4];
  for (uint8_t b = 0; b < r.uidLen; b++) {
    sprintf(hex, "%02X", r.uid[b]);
    s += hex; s += " ";
  }
  s += "| Время: " + String(r.ts / 1000) + " c | Данные: ";
  s += r.dataLen ? String(r.data) : "(только UID)";
  return s;
}

#if USB_KB
void dumpToNotepad() {
  Keyboard.press(KEY_LEFT_GUI); Keyboard.press('r');   // Win+R
  delay(120); Keyboard.releaseAll();
  delay(800);
  Keyboard.print("notepad");
  Keyboard.press(KEY_RETURN);  Keyboard.releaseAll();
  delay(1500);

  if (recCount == 0) { Keyboard.print("(база пуста)"); Keyboard.press(KEY_RETURN); Keyboard.releaseAll(); return; }
  for (uint8_t i = 0; i < recCount; i++) {
    Keyboard.print(recordToText(i));
    Keyboard.press(KEY_RETURN); Keyboard.releaseAll();
    delay(40);
  }
}
#endif

// ---------- основной код ----------

void setup() {
  Serial.begin(115200);
  EEPROM.begin(EEPROM_SIZE);
  recCount = EEPROM.read(0);
  if (recCount > MAX_RECORDS) recCount = 0;

  SPI.begin(SCK_PIN, MISO_PIN, MOSI_PIN, SS_PIN);
  rfid.PCD_Init();
  Serial.println("Готов. Поднесите телефон или карту...");

#if USB_KB
  Keyboard.begin();
  delay(2000);        // даём ОС распознать клавиатуру
  dumpToNotepad();    // при подключении к ПК сразу печатаем базу
#endif
}

void loop() {
  if (!rfid.PICC_IsNewCardPresent()) return;
  if (!rfid.PICC_ReadCardSerial()) return;

  isoPcb = 0x02;
  char text[DATA_MAX + 1] = "";
  bool hasNdef = false;

  if (rfid.uid.sak & 0x20) {                 // ISO 14443-4 — похоже на телефон
    hasNdef = readNdefFromPhone(text, DATA_MAX);
  }

  addRecord(millis(), rfid.uid.uidByte, rfid.uid.size, hasNdef ? text : NULL);

  Serial.print("UID: ");
  for (uint8_t i = 0; i < rfid.uid.size; i++)
    Serial.printf("%02X ", rfid.uid.uidByte[i]);
  Serial.println(hasNdef ? String(" | NDEF: ") + text : " | только UID");

  rfid.PICC_HaltA();
  delay(1500);
}
